CREATE TABLE IF NOT EXISTS iam.password_credential (account_id uuid PRIMARY KEY REFERENCES iam.account(id) ON DELETE RESTRICT, state varchar(16) NOT NULL, algorithm varchar(16) NOT NULL, algorithm_parameters jsonb NOT NULL, password_hash bytea NOT NULL, password_version bigint NOT NULL, changed_at timestamptz NOT NULL, temporary_expires_at timestamptz, failed_attempt_count integer NOT NULL DEFAULT 0, locked_until timestamptz);
CREATE TABLE IF NOT EXISTS iam.session (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES iam.account(id) ON DELETE RESTRICT, channel varchar(32) NOT NULL, token_family_id uuid NOT NULL, assurance_level varchar(8) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz, revoke_reason text);
CREATE TABLE IF NOT EXISTS iam.session_context (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES iam.session(id) ON DELETE RESTRICT, workspace varchar(20) NOT NULL, audience varchar(32) NOT NULL, authz_version bigint NOT NULL, policy_revision bigint NOT NULL, organization_revision bigint NOT NULL, assurance_level varchar(8) NOT NULL, restriction varchar(32) NOT NULL DEFAULT 'NORMAL', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, revoked_at timestamptz);
